CREATE POLICY unidades_insert_authorized ON public.unidades FOR INSERT TO authenticated WITH CHECK (public.is_master(auth.uid()) OR public.has_permission(auth.uid(), 'unidade.gerenciar', id, secretaria_id));
CREATE POLICY unidades_update_authorized ON public.unidades FOR UPDATE TO authenticated USING (public.is_master(auth.uid()) OR public.has_permission(auth.uid(), 'unidade.gerenciar', id, secretaria_id)) WITH CHECK (public.is_master(auth.uid()) OR public.has_permission(auth.uid(), 'unidade.gerenciar', id, secretaria_id));
ALTER POLICY pol_setores_write ON public.setores USING (public.is_master(auth.uid()) OR public.has_permission(auth.uid(), 'unidade.gerenciar', unidade_id)) WITH CHECK (public.is_master(auth.uid()) OR public.has_permission(auth.uid(), 'unidade.gerenciar', unidade_id));